
export const KB = [];
const E = (id, t, k, a, more, rel) => KB.push({ id, t, k, a, more, rel: rel || [] });
const L = (...x) => x.join("\n");

/* ---------- basics ---------- */
E("what", "What is a tropical cyclone?", "cyclone definition meaning hurricane typhoon storm what is a cyclone rotating low pressure system spiral thunderstorms warm ocean",
  "A tropical cyclone is a large, rotating storm that forms over warm tropical oceans. It has a low-pressure centre, a closed circulation, spiralling bands of thunderstorms and very strong winds. It is powered by heat and moisture from the sea, and it weakens quickly once it moves over land or cold water. Winds spin counter-clockwise around the centre in the Northern Hemisphere and clockwise in the Southern Hemisphere.",
  "Tropical cyclones are usually 200 to 1,000 km wide and last about a week. Their main dangers are storm surge, extreme rain and flooding, and destructive winds.", ["formation", "names", "structure"]);
E("names", "What is the difference between a cyclone, a hurricane and a typhoon?", "why are cyclones called hurricanes in america why is it called hurricane in america why typhoon in japan why different names in different countries hurricane typhoon cyclone same difference different names regional name atlantic pacific indian ocean are hurricanes and cyclones the same thing same or different hurricane typhoon cyclone are they the same",
  "They are the same weather system with different regional names. It is called a hurricane in the North Atlantic and the central and eastern North Pacific, a typhoon in the western North Pacific, and a cyclone (or tropical cyclone) in the North Indian Ocean, the South Indian Ocean, the Australian region and the South Pacific. The names depend only on where the storm forms.", null, ["what", "basins"]);
E("tornado", "How is a cyclone different from a tornado?", "tornado twister difference compare cyclone versus tornado size",
  "A tropical cyclone is hundreds of kilometres wide, lasts days and is driven by warm ocean water. A tornado is usually only tens to a few hundred metres wide, lasts minutes and forms inside a single thunderstorm over land. Tornadoes can form in the outer rainbands of a landfalling cyclone, but the two are different phenomena.", null, ["what"]);
E("extratropical", "What is the difference between a tropical and an extratropical cyclone?", "extratropical mid latitude temperate cyclone nor easter frontal cold core warm core difference",
  "A tropical cyclone has a warm core and gets its energy from warm ocean water, so it forms in the tropics and has no fronts. An extratropical (mid-latitude) cyclone has fronts and a cold core and gets its energy from temperature contrasts between air masses. A tropical cyclone can turn extratropical when it moves to higher latitudes and cooler water.", null, ["what", "anticyclone"]);
E("anticyclone", "What is an anticyclone?", "anticyclone high pressure opposite of cyclone clear weather sinking air",
  "An anticyclone is a high-pressure system where air sinks and spreads outwards. It spins the opposite way to a cyclone (clockwise in the Northern Hemisphere) and usually brings clear, calm weather. Anticyclones, such as the subtropical ridge, also help steer cyclones.", null, ["steering"]);
E("etymology", "Where does the word cyclone come from?", "etymology origin word cyclone meaning greek kyklos piddington coil of snake history of the word",
  "The word comes from the Greek kyklos, meaning circle or the coil of a snake. Henry Piddington, who studied storms in the Bay of Bengal, introduced it in 1848.", null, ["what"]);

/* ---------- formation ---------- */
E("formation", "How do tropical cyclones form?", "how do cyclones form in bay of bengal how do cyclones gain strength how do cyclones grow how do cyclones form formation genesis develop start born origin cyclogenesis created how are cyclones formed",
  L("A cyclone forms when a cluster of thunderstorms over warm ocean water begins to organise:", "• Warm, moist air rises from the sea surface.", "• The water vapour condenses, releasing heat that warms the air and lowers the pressure at the surface.", "• Air rushes in towards the low pressure, is turned by the Earth's rotation and starts to spin.", "• If the winds aloft are weak, the system keeps strengthening, passing through depression, storm and cyclone stages."),
  "This feedback loop is why it needs very warm sea water, moist air, weak wind shear and a starting disturbance.", ["conditions", "coriolis", "lifecycle"]);
E("conditions", "What conditions does a cyclone need to form?", "conditions requirements ingredients needed favourable sea surface temperature 26.5 warm water shear humidity coriolis disturbance",
  L("Cyclones need several things at once:", "• Sea surface temperature of at least about 26.5 °C, through a depth of about 50 m.", "• A moist lower and middle atmosphere.", "• Low vertical wind shear.", "• A pre-existing disturbance such as a low-pressure area or monsoon trough.", "• Enough distance from the equator (roughly 5 degrees of latitude) for the Coriolis effect to spin the system."), null, ["sst", "shear", "coriolis"]);
E("coriolis", "What is the Coriolis effect and why does it matter for cyclones?", "coriolis force effect earth rotation spin deflect why rotate",
  "The Coriolis effect is the apparent deflection of moving air caused by the Earth's rotation. It turns air that is flowing in towards a low-pressure centre so that it circles the centre instead of filling it. That is why cyclones spin, counter-clockwise in the Northern Hemisphere and clockwise in the Southern Hemisphere.", null, ["equator", "spin"]);
E("equator", "Why do cyclones not form at the equator?", "equator why not form near equator no cyclones zero latitude coriolis weak",
  "The Coriolis effect is almost zero at the equator, so air flowing towards a low-pressure area cannot be set spinning. Cyclones rarely form within about 5 degrees of latitude of the equator for this reason.", null, ["coriolis", "conditions"]);
E("spin", "Why do cyclones rotate in different directions in each hemisphere?", "direction rotation clockwise anticlockwise counter clockwise northern southern hemisphere spin",
  "Because the Coriolis effect turns moving air to the right in the Northern Hemisphere and to the left in the Southern Hemisphere. Cyclones therefore spin counter-clockwise north of the equator and clockwise south of it.", null, ["coriolis"]);
E("lifecycle", "What are the stages in the life of a cyclone?", "life cycle stages of cyclone phases formation intensification mature decay dissipation stages",
  L("A cyclone goes through four broad stages:", "• Formation: a disturbance over warm water begins to organise.", "• Intensification: it becomes a depression, then a storm, then a cyclone as winds rise and an eye may form.", "• Maturity: it reaches peak intensity and its wind field is at its widest.", "• Decay: it weakens over land, cold water or in strong wind shear."), null, ["formation", "decay"]);
E("lifespan", "How long does a cyclone last?", "how long lifespan duration last days live time life of cyclone",
  "Most tropical cyclones last about a week. Some fade in a day or two, and a few last much longer. Hurricane John in 1994 lasted 31 days, the longest on record.", null, ["records"]);
E("size", "How big is a cyclone?", "size diameter width how large wide big cyclone radius",
  "Most tropical cyclones are 200 to 1,000 km across. The eye is typically 30 to 65 km wide, though it can be anywhere from about 10 to over 200 km. Size and strength are different: a small cyclone can be very intense, and a large one can be weaker but affect a wider area.", null, ["eye", "records"]);
E("speed", "How fast do cyclones move?", "speed of movement translation forward motion how fast moving travel speed cyclone moves slow fast",
  "Most move at 10 to 30 km/h, though they can speed up when caught in strong steering winds. A slow or stalled cyclone is especially dangerous because it keeps dumping rain on the same area. Forward speed is different from the wind speed inside the storm.", null, ["steering", "rain"]);
E("energy", "Where does a cyclone get its energy?", "energy source power fuel heat engine latent heat ocean evaporation how powerful",
  "A cyclone works like a heat engine. It draws heat from warm sea water by evaporation. When the water vapour condenses into cloud, it releases latent heat, which warms the core, lowers pressure and drives stronger inflow. Cut off from warm water, for example over land, the storm loses its fuel and weakens.", null, ["sst", "land"]);

/* ---------- structure ---------- */
E("structure", "What is the structure of a cyclone?", "structure parts anatomy eye eyewall rainbands outflow inflow components of a cyclone",
  L("A mature cyclone has these parts:", "• Eye: a calm, often clear centre.", "• Eyewall: a ring of the strongest thunderstorms, with the highest winds and heaviest rain.", "• Spiral rainbands: curved lines of storms that spiral inwards.", "• Inflow at the surface and a broad outflow of air at the top, high in the atmosphere.", "• A warm core, which keeps the central pressure low."), null, ["eye", "eyewall", "rainbands"]);
E("eye", "What is the eye of a cyclone?", "eye of the storm calm centre clear sinking air eye diameter size eye formation how big wide diameter size of the eye width of eye how large is the eye",
  "The eye is the calm, often cloud-free centre of a strong cyclone. Air sinks there, which dries and warms it and clears the sky. It is usually 30 to 65 km wide. The eye appears when a storm is well organised, so a clear, round eye on satellite images usually means a strong, mature cyclone.",
  "The weather in the eye is deceptively calm, but the eyewall is right next to it. When the eye passes, the strong winds return suddenly from the opposite direction.", ["eyewall", "eyetrap"]);
E("eyewall", "What is the eyewall?", "eyewall ring strongest winds heaviest rain thunderstorms around eye",
  "The eyewall is the ring of towering thunderstorms around the eye. It has the strongest winds and heaviest rain in the cyclone. If the eyewall moves over a coast, that is where the worst wind damage happens.", null, ["eye", "erc"]);
E("erc", "What is an eyewall replacement cycle?", "eyewall replacement cycle erc concentric eyewall double eyewall weaken restrengthen",
  "In some intense cyclones a second, larger eyewall forms around the first. The inner eyewall then fades and is replaced by the outer one. During this process the winds often weaken for a while and the eye gets bigger, and then the storm may strengthen again. It makes intensity forecasts harder.", null, ["eyewall", "rapid"]);
E("rainbands", "What are rainbands?", "rainbands spiral bands outer bands convection thunderstorms arms",
  "Rainbands are curved lines of showers and thunderstorms that spiral into the centre of a cyclone. They can extend hundreds of kilometres from the eye, bring squalls and heavy rain long before the centre arrives, and sometimes spawn tornadoes.", null, ["structure", "rain"]);
E("cdo", "What is the central dense overcast?", "central dense overcast cdo cloud shield cirrus outflow satellite",
  "The central dense overcast (CDO) is the thick, round patch of cold cloud tops over the centre of a cyclone seen on satellite images. A larger, more symmetric and colder CDO usually means a stronger storm.", null, ["dvorak", "cloudtop"]);
E("warmcore", "What is a warm-core system?", "warm core cold core system tropical cyclone temperature centre",
  "A warm-core system has air at its centre that is warmer than the surroundings. Tropical cyclones are warm-core because heat released by condensation warms the column. Mid-latitude storms with fronts are generally cold-core.", null, ["energy", "extratropical"]);
E("outflow", "What is outflow in a cyclone?", "outflow upper level divergence anticyclone exhaust high level",
  "Outflow is the air that spreads out at the top of a cyclone, about 10 to 15 km up. Good outflow acts like an exhaust and lets the storm draw in more air at the surface, so a strong, symmetric outflow helps it to strengthen.", null, ["structure", "shear"]);

/* ---------- scales ---------- */
E("saffir", "What is the Saffir-Simpson scale?", "saffir simpson scale category 1 2 3 4 5 hurricane wind scale categories explained intensity scale what category what are the categories of cyclone category levels types of cyclones classification of cyclones kinds hurricane categories",
  L("The Saffir-Simpson scale rates a cyclone from Category 1 to 5 by its 1-minute sustained wind speed:", "• Category 1: 64 to 82 kt (119 to 153 km/h)", "• Category 2: 83 to 95 kt (154 to 177 km/h)", "• Category 3: 96 to 112 kt (178 to 208 km/h)", "• Category 4: 113 to 136 kt (209 to 251 km/h)", "• Category 5: 137 kt or more (252 km/h or more)", "Below Category 1 are tropical depressions (under 34 kt) and tropical storms (34 to 63 kt). CycloneX uses these thresholds."),
  "The scale only measures wind. It does not include storm surge, rainfall or flooding, which often cause the most deaths, so a low category does not mean low danger.", ["imd", "averaging", "windconv"]);
E("imd", "How does the IMD classify cyclones?", "imd classification scale india meteorological department categories depression deep depression cyclonic storm severe very severe extremely severe super cyclonic storm difference between depression and deep depression cyclonic storm severe very severe types of cyclone in india",
  L("The India Meteorological Department (IMD) classifies systems over the North Indian Ocean by 3-minute sustained wind:", "• Low pressure area: below 17 kt (31 km/h)", "• Depression: 17 to 27 kt (31 to 49 km/h)", "• Deep depression: 28 to 33 kt (50 to 61 km/h)", "• Cyclonic storm: 34 to 47 kt (62 to 88 km/h)", "• Severe cyclonic storm: 48 to 63 kt (89 to 117 km/h)", "• Very severe cyclonic storm: 64 to 89 kt (118 to 165 km/h)", "• Extremely severe cyclonic storm: 90 to 119 kt (166 to 220 km/h)", "• Super cyclonic storm: 120 kt (221 km/h) or more"),
  "A system is given a name once it reaches the cyclonic storm stage (34 kt).", ["saffir", "naming", "averaging"]);
E("wmo", "How does the WMO classify tropical cyclones?", "wmo world meteorological organization classification tropical depression tropical storm severe tropical storm typhoon",
  "The WMO uses broad classes based on wind: a tropical depression (below 34 kt), a tropical storm (34 to 47 kt), a severe tropical storm (48 to 63 kt) and a tropical cyclone, hurricane or typhoon (64 kt or more). Different centres then add their own finer scales, such as the IMD scale in India or the Saffir-Simpson scale in the Americas.", null, ["imd", "saffir"]);
E("averaging", "What is the difference between 1-minute, 3-minute and 10-minute winds?", "averaging period 1 minute 3 minute 10 minute sustained wind difference gust different agencies numbers disagree",
  "Agencies average the wind over different periods. The US uses a 1-minute average, the IMD uses 3 minutes and the WMO standard is 10 minutes. Longer averages smooth out gusts, so the same storm has a higher 1-minute number than 10-minute number. The WMO suggests that a 10-minute wind is about 0.93 times the 1-minute wind. That is why different agencies can quote different numbers for the same cyclone.", null, ["sustained", "saffir", "imd"]);
E("sustained", "What is the difference between sustained wind and a gust?", "sustained wind gust difference peak wind maximum sustained",
  "Sustained wind is the average wind over a set period (1, 3 or 10 minutes). A gust is a brief peak, usually lasting a few seconds, and is typically 20 to 40 percent higher than the sustained wind. Cyclone categories use sustained wind, but gusts do much of the damage.", null, ["averaging"]);
E("cat6", "Is there a Category 6?", "category 6 cat 6 does it exist beyond category 5 higher",
  "No. The Saffir-Simpson scale stops at Category 5 (137 kt or more) because the damage from any wind above that level is already catastrophic. Some scientists have suggested adding a Category 6, but it is not official.", null, ["saffir"]);
E("supercyclone", "What is a super cyclone?", "super cyclone supercyclonic storm odisha 1999 super cyclone definition 120 knots 221 km/h",
  "In the IMD scale, a super cyclonic storm has sustained winds of 120 kt (221 km/h) or more. Examples in the Bay of Bengal include the 1999 Odisha super cyclone and Amphan in 2020.", null, ["imd", "odisha1999", "amphan"]);

/* ---------- intensity ---------- */
E("rapid", "What is rapid intensification?", "rapid intensification ri explosive deepening suddenly strengthen quickly 30 knots 24 hours",
  "Rapid intensification is when a cyclone's maximum sustained wind rises by at least 30 kt (about 55 km/h) in 24 hours. It needs very warm, deep water, low wind shear and moist air. It is one of the hardest things to forecast and makes storms more dangerous because there is less time to prepare.", null, ["sst", "shear", "ohc"]);
E("shear", "What is wind shear and how does it affect cyclones?", "wind shear vertical shear effect weaken tilt ventilate dry air upper level winds how does wind shear affect cyclones",
  "Vertical wind shear is the change in wind speed or direction with height. Low shear (below roughly 10 to 15 kt) lets a cyclone's thunderstorms stack straight up and strengthen. High shear (above about 20 kt) tilts the storm and blows its heat and moisture away, which weakens it or stops it forming.", null, ["rapid", "conditions"]);
E("sst", "How warm does the sea have to be for a cyclone?", "ocean ocean heat ocean water the ocean and cyclones what does the ocean do for a cyclone role of ocean in cyclone how does temperature affect cyclones ocean heat fuel role of sea warm water fuel how does sea temperature affect sea surface temperature sst 26.5 warm water ocean temperature needed degrees how warm how warm should sea water be temperature degrees needed for cyclone formation water temperature requirement",
  "Cyclones generally need sea surface temperatures of at least about 26.5 °C, with warm water down to roughly 50 m. Warmer, deeper water allows stronger storms. Water of about 29 to 30 °C, as in the Arabian Sea before the monsoon, can support rapid strengthening.", null, ["ohc", "conditions"]);
E("ohc", "What is ocean heat content?", "ocean heat content ohc depth warm layer tropical cyclone heat potential",
  "Ocean heat content measures how much heat is stored in the upper ocean, not just at the surface. A deep layer of warm water means the storm cannot cool the surface by churning up cold water from below, so it can keep strengthening. Eddies of warm water are often linked to rapid intensification.", null, ["sst", "upwelling"]);
E("upwelling", "Does a cyclone cool the ocean?", "upwelling cold wake cool sea surface after cyclone mixing ocean response",
  "Yes. The strong winds churn the ocean and bring cooler water up from below, leaving a cold wake behind the storm. Slow-moving cyclones cool the surface more and can weaken themselves.", null, ["ohc"]);
E("dryair", "How does dry air affect a cyclone?", "dry air intrusion weaken dry mid level humidity moisture",
  "Dry air that gets into the core suppresses thunderstorms and makes the cyclone weaker and more lopsided. Water vapour satellite images show dry air as dark areas, which is one reason forecasters watch that channel.", null, ["wvchannel"]);
E("land", "Why do cyclones weaken over land?", "land weaken decay landfall dissipate why weaken after landfall friction fuel what happens when a cyclone hits land after landfall over land effect on land inland",
  "Over land a cyclone loses its fuel of warm, moist air from the sea, and friction with the ground slows the wind. The storm usually weakens quickly, though it can still bring heavy rain and flooding far inland for a day or more.", null, ["energy", "rain"]);
E("decay", "How do cyclones die out?", "dissipate dissipation end die decay weaken cold water shear land",
  "A cyclone decays when it moves over land or cold water, runs into strong wind shear or dry air, or becomes extratropical. Its remains can still cause heavy rain.", null, ["land", "lifecycle"]);
E("pressure", "What does the central pressure of a cyclone tell us?", "pressure at the centre of a cyclone pressure at the center what is the pressure in the eye how low is the pressure central pressure minimum sea level pressure hpa millibar mb low pressure strength lowest pressure",
  "Normal sea-level pressure is about 1013 hPa. In a cyclone the central pressure drops, and a lower value generally means stronger winds. Cyclones with central pressures below about 950 hPa are major cyclones, and the lowest ever measured was 870 hPa in Typhoon Tip (1979).", null, ["records", "hpa"]);
E("ace", "What is accumulated cyclone energy?", "accumulated cyclone energy ace index season activity measure",
  "Accumulated cyclone energy (ACE) measures a storm's or season's total wind energy. It is calculated by squaring a storm's maximum sustained wind (in knots) every 6 hours while it is at tropical-storm strength or more, adding these up and dividing by 10,000. It rewards both strong and long-lived storms.", null, ["saffir"]);
E("radii", "What are wind radii?", "wind radii 34 50 64 knot radius extent of strong winds gale force how far wind extends quadrant",
  "Wind radii give the distance from the centre out to which winds of 34, 50 and 64 kt (the thresholds for storm, strong and hurricane force) extend, usually by quadrant. They show how wide the damaging winds are and are used to plan evacuations. CycloneX draws them on the Dashboard map as wind radii.", null, ["size"]);

/* ---------- hazards ---------- */
E("surge", "What is storm surge?", "storm surge sea level rise coastal flooding water pushed ashore tide wave inundation how high surge how high how much height metres dangerous why is storm surge dangerous storm surge height",
  "Storm surge is the abnormal rise of sea level caused by a cyclone's winds pushing water towards the coast, plus the effect of the low pressure. It is usually the most dangerous hazard of a landfalling cyclone, because it can flood coastal areas with several metres of sea water in a short time. How high it gets depends on the cyclone's strength, size and speed, the shape of the coast, how shallow the sea is, and the tide.",
  "Surge is not the same as waves, and it is not a tsunami. Surge is driven by the storm itself, rises over hours and is usually highest to the right of the storm's path in the Northern Hemisphere.", ["tide", "tsunami", "deaths"]);
E("tide", "What is storm tide?", "storm tide astronomical tide high tide combined surge spring tide",
  "Storm tide is the total water level at the coast: the storm surge plus the normal astronomical tide. A surge that arrives at high tide, especially a spring tide, is much more damaging than the same surge at low tide.", null, ["surge"]);
E("tsunami", "Is a storm surge the same as a tsunami?", "tsunami vs storm surge difference compare earthquake",
  "No. A tsunami is caused by an undersea earthquake, landslide or volcano and its waves travel across the ocean. A storm surge is caused by a cyclone's winds and low pressure and is limited to the area near the storm.", null, ["surge"]);
E("rain", "How much rain do cyclones bring?", "rain rainfall flood heavy rain precipitation flooding inland cloudburst how much rain",
  "Cyclones can drop several hundred millimetres of rain in a day or two. Hurricane Harvey in 2017 dropped over 1,500 mm in parts of Texas. Rain can cause flash floods, landslides and river floods, even far inland and after the winds have weakened. Slow-moving storms and warmer air, which holds more moisture, make it worse.", null, ["speed", "deaths"]);
E("wind", "How does cyclone wind cause damage?", "wind damage destructive winds buildings kutcha houses roofs trees power lines debris",
  "Wind damage grows very fast with speed: doubling the wind speed multiplies the force on a structure by about four. Winds tear off roofs, topple trees and power lines, and throw debris that causes more damage and injury. Light, kutcha and poorly anchored structures are the most at risk.", null, ["saffir"]);
E("deaths", "What causes most deaths in cyclones?", "deaths casualties killed fatalities danger deadliest hazard why people die cause of death",
  "Water, not wind, causes most deaths: storm surge in coastal areas and flooding from rain. Many of the deadliest cyclones in history, such as the 1970 Bhola cyclone and Nargis in 2008, were killers mainly because of surge in low-lying deltas. Early warning and evacuation are what save lives.", null, ["surge", "rain", "evacuation"]);
E("tornadoes", "Can cyclones cause tornadoes?", "tornadoes in cyclones landfall spawn tornado rainbands",
  "Yes. Landfalling cyclones can spawn tornadoes in their outer rainbands, mostly in the right-front part of the storm as seen along the direction of travel. They are usually weaker and shorter-lived than tornadoes in other storms.", null, ["rainbands"]);
E("erosion", "How do cyclones affect the coast?", "coastal erosion beach damage mangroves protection coastline impact environment",
  "Surge and waves erode beaches, wash over low land, damage mangroves and contaminate fields and drinking water with salt. Mangroves, coral reefs and dunes help to reduce the damage, which is why protecting them is part of coastal defence.", null, ["surge"]);

/* ---------- track and forecast ---------- */
E("steering", "What decides where a cyclone goes?", "steering track direction motion why cyclone move path recurve subtropical ridge trough beta drift westerlies",
  "A cyclone is mostly carried along by the large-scale winds around it, called the steering flow. In the tropics it is usually pushed west or north-west by the trade winds and the subtropical high-pressure ridge. Where it meets a trough or the mid-latitude westerlies, it can turn towards the pole and then east, which is called recurving. The storm's own rotation adds a small drift towards the north-west as well.", null, ["recurve", "fujiwhara"]);
E("recurve", "What does it mean when a cyclone recurves?", "recurve recurvature turn curve change direction northeast",
  "Recurvature is when a cyclone that has been moving west or north-west turns towards the pole and then east or north-east, usually because it has reached a trough in the westerlies. Recurving storms in the North Indian Ocean often head towards the Indian west coast or the Gujarat and Pakistan coasts.", null, ["steering"]);
E("fujiwhara", "What is the Fujiwhara effect?", "fujiwhara effect two cyclones interact merge binary orbit each other",
  "When two cyclones come within roughly 1,000 to 1,400 km of each other they begin to rotate around a common centre. They may then merge or fling each other off course. It is called the Fujiwhara effect, after the Japanese meteorologist who described it.", null, ["steering"]);
E("stall", "What happens when a cyclone stalls?", "stall stationary slow moving stuck loiter",
  "When a cyclone stalls or moves very slowly, it can pour rain on the same area for many hours or days and cool the sea beneath it. This is why slow storms such as Harvey in 2017 caused such enormous floods.", null, ["rain", "speed"]);
E("cone", "What is the cone of uncertainty?", "cone of uncertainty forecast cone track error cone meaning white cone shaded area",
  "The cone shows the area where the centre of the cyclone is likely to go, based on past forecast errors. The cone is drawn so that the centre stays inside it about two-thirds of the time. It does not show the size of the storm or where the impacts will be, and dangerous weather often reaches well outside the cone. CycloneX draws it on the Dashboard map.", null, ["accuracy", "ensemble"]);
E("ensemble", "What are ensemble forecasts?", "ensemble members spaghetti plot multiple model runs probabilistic forecast 52 members",
  "An ensemble is a set of forecasts run from slightly different starting conditions or with slightly different physics. If all members agree, confidence is high. If they spread out, the forecast is uncertain. CycloneX's time-series forecaster uses a 52-member ensemble to produce the track, intensity, landfall and its confidence.", null, ["cone", "models"]);
E("models", "What models are used to forecast cyclones?", "how do meteorologists predict the path of a cyclone how do forecasters predict track how are cyclones predicted weather forecasting methods forecast models gfs ecmwf hwrf hafs numerical weather prediction nwp global regional models which models",
  "Cyclone forecasts combine global numerical models such as ECMWF's IFS and the US GFS, regional high-resolution models such as HWRF and HAFS, statistical models, ensembles and expert judgement. Forecasters in each country, such as the IMD, blend them with satellite and radar data.", null, ["accuracy", "ai"]);
E("accuracy", "How accurate are cyclone forecasts?", "forecast accuracy reliable how good track error intensity error prediction skill improved",
  "Track forecasts have improved steadily over recent decades and are generally good out to 3 to 5 days, with typical errors of roughly 70 to 120 km at 24 hours that grow with lead time. Intensity forecasts, especially rapid intensification, remain much harder. Uncertainty always grows with lead time, which is why forecasts show confidence values and a cone.", null, ["cone", "rapid"]);
E("ai", "Can AI and machine learning forecast cyclones?", "ai machine learning deep learning neural network graphcast pangu forecasting cyclone artificial intelligence",
  "Yes. AI weather models such as GraphCast and Pangu-Weather have shown cyclone track forecasts that rival traditional models at a fraction of the computing cost, and AI is also used to estimate intensity from satellite images. CycloneX follows this approach, with a convolutional network to find and classify cyclones, a transformer to read image sequences and a time-series ensemble to forecast. In this prototype the model outputs are simulated.", null, ["models", "cnn"]);
E("cnn", "What is a convolutional neural network?", "cnn convolutional neural network image recognition deep learning what is cnn",
  "A convolutional neural network (CNN) is a deep-learning model that learns to recognise patterns in images. For cyclones it can learn the spiral cloud pattern, eye and cold cloud tops from satellite images, find the centre and estimate the storm's stage and intensity.", null, ["ai", "transformer"]);
E("transformer", "What is a transformer model?", "transformer attention sequence model what is transformer time series image sequence",
  "A transformer is a deep-learning model that uses an attention mechanism to relate all items in a sequence to one another. Applied to a series of satellite frames taken every few hours, it can learn how a cyclone's cloud pattern, shape and temperature are changing and whether it is strengthening or weakening.", null, ["ai", "cnn"]);

/* ---------- observation ---------- */
E("satellites", "How are cyclones observed from space?", "satellite observation monitoring how do satellites track cyclones insat geostationary polar orbiting imagery",
  "Geostationary satellites such as India's INSAT-3D, 3DR and 3DS and Japan's Himawari sit over one spot and image the same area every few minutes, so they can follow a cyclone continuously. Polar-orbiting satellites pass over less often but carry instruments, such as scatterometers and microwave sensors, that measure ocean winds and the storm's internal structure.", null, ["channels", "scatterometer"]);
E("channels", "What do the visible, infrared and water vapour channels show?", "visible infrared water vapour vapor channel imagery bands what do they show satellite image types",
  L("Satellite imagers see a cyclone in different wavelengths:", "• Visible: reflected sunlight, showing cloud structure, the eye and spiral bands, but only in daylight.", "• Infrared: heat from cloud tops, showing how cold (and so how high) they are, day and night.", "• Water vapour: moisture high in the atmosphere, showing dry air and the winds that steer the storm."), null, ["cloudtop", "satellites"]);
E("cloudtop", "Why do cold cloud tops mean a stronger cyclone?", "cloud top temperature cold cloud tops infrared brightness temperature stronger storm higher clouds minus 80",
  "Cloud-top temperature falls with height. The colder the cloud tops (for example around -80 °C or below), the taller and more intense the thunderstorms. A big area of very cold tops close to the centre means strong convection and usually a strong or strengthening cyclone.", null, ["channels", "dvorak"]);
E("wvchannel", "Why is the water vapour channel useful?", "water vapour channel useful moisture dry air steering",
  "The water vapour channel shows moisture in the upper atmosphere, even where there are no clouds. Forecasters use it to spot dry air that could weaken a cyclone and to see the troughs and ridges that steer it.", null, ["channels", "dryair"]);
E("dvorak", "What is the Dvorak technique?", "dvorak technique t number current intensity ci estimate intensity from satellite images",
  "The Dvorak technique estimates a cyclone's intensity from satellite images alone. An analyst or algorithm examines the cloud pattern (curved bands, central dense overcast, eye) and gives it a T-number from 1 to 8, which is converted to wind speed. For example T3.0 is about 45 kt and T5.0 about 90 kt. It is the standard method for storms that aircraft or ships cannot reach.", null, ["cdo", "cloudtop"]);
E("scatterometer", "What is a scatterometer?", "scatterometer ascat scatsat ocean surface wind measure radar satellite",
  "A scatterometer is a satellite radar that measures ocean-surface wind speed and direction from how the sea surface scatters radio waves. India's ScatSat-1 and the ASCAT instrument on Europe's Metop satellites are examples. They help to map the extent of strong winds around a cyclone.", null, ["satellites", "radii"]);
E("radar", "How is radar used to track cyclones?", "radar doppler weather radar dwr rain wind near coast imd radar network",
  "Doppler weather radars along the coast scan the rain and wind structure inside a cyclone when it comes within a few hundred kilometres. They can show the eye and eyewall, estimate rainfall and wind, and are very important in the last hours before landfall. The IMD operates a network of them.", null, ["satellites"]);
E("buoys", "What other instruments measure cyclones?", "buoys ships aircraft hurricane hunters dropsonde reconnaissance in situ observation ocean moored buoy",
  "Moored ocean buoys, ships, coastal stations and weather balloons measure pressure, wind, waves and sea temperature directly. In the Atlantic, aircraft known as hurricane hunters fly into storms and drop instruments called dropsondes. In the North Indian Ocean the main tools are satellites, radars and buoys.", null, ["satellites", "radar"]);
E("besttrack", "What is a best track?", "best track archive hurricane database ibtracs post analysis historical record",
  "A best track is the official, after-the-event record of a cyclone's position and intensity, produced by re-analysing all the data. Best-track archives are used to train and verify forecast models, as CycloneX does.", null, ["satellites"]);

/* ---------- warnings ---------- */
E("landfall", "What does landfall mean?", "landfall definition meaning make landfall crosses coast direct hit brush",
  "Landfall is when the centre of a cyclone moves from sea to land across the coastline. A storm that skirts the coast without its centre crossing is not a landfall, but it can still cause damage because the strongest winds and surge extend far from the centre.", null, ["surge", "land"]);
E("watchwarn", "What is the difference between a cyclone watch and a warning?", "watch vs warning difference alert advisory pre cyclone watch cyclone alert",
  "A watch or alert means conditions could become dangerous, so you should be ready. A warning means dangerous conditions are expected, so you should take action now. The IMD issues them in stages: Pre-cyclone Watch about 72 hours before the expected onset of bad weather, Cyclone Alert about 48 hours before, Cyclone Warning about 24 hours before and a Post-landfall Outlook about 12 hours before landfall.", null, ["colours", "imdwarn"]);
E("imdwarn", "How does the IMD warn about cyclones?", "how long before landfall are warnings issued lead time how early are warnings given when are warnings issued 72 hours 48 hours 24 hours imd warnings bulletin stages pre cyclone watch alert warning post landfall outlook issue who issues warnings india how are warnings sent to people communicated informed how does india warn people",
  "The IMD, through its Regional Specialised Meteorological Centre (RSMC) in New Delhi, issues cyclone bulletins for the North Indian Ocean. The stages are Pre-cyclone Watch (about 72 h ahead), Cyclone Alert (48 h), Cyclone Warning (24 h) and Post-landfall Outlook (12 h). Bulletins go to state governments, the NDMA, ports, fishermen and the media. For real emergencies always follow the IMD and your state disaster management authority.", null, ["colours", "agencies"]);
E("colours", "What do the colour-coded warnings mean?", "colour code color code green yellow orange red warning levels imd meaning alert colours",
  L("The IMD uses four colours:", "• Green: no warning, no action needed.", "• Yellow: watch, be aware and keep updated.", "• Orange: alert, be prepared to act.", "• Red: warning, take action now."), "CycloneX's Early warning page uses the same four levels.", ["watchwarn"]);
E("agencies", "Which agencies handle cyclones in India?", "ndma ndrf imd incois sdma agencies india disaster management who is responsible",
  L("In India:", "• IMD forecasts and warns.", "• NDMA, set up under the Disaster Management Act 2005, plans and coordinates national disaster management.", "• NDRF is the specialist national response force, and SDRF and state disaster management authorities work at state level.", "• INCOIS provides ocean-state forecasts and the tsunami early warning service.", "• District administrations carry out evacuations and run the shelters."), null, ["imdwarn", "shelters"]);
E("rsmc", "Which centres are responsible for cyclones around the world?", "rsmc regional specialised meteorological centre nhc jma jtwc meteo france bom who is responsible forecasting centres",
  "The WMO designates Regional Specialised Meteorological Centres. For example, the IMD in New Delhi covers the North Indian Ocean, the US National Hurricane Center covers the Atlantic and eastern Pacific, the Japan Meteorological Agency covers the western Pacific and Météo-France at La Réunion covers the South-West Indian Ocean. The Joint Typhoon Warning Center, a US military centre, issues separate warnings for several basins.", null, ["basins", "naming"]);

/* ---------- basins, seasons, naming ---------- */
E("number", "How many cyclones form each year?", "how many cyclones per year annually average number of cyclones every year world global india frequency count",
  "About 80 to 90 named tropical storms form around the world each year. The North Indian Ocean accounts for only about 5 to 6 percent of them, so it has a handful of cyclonic storms a year, and the Bay of Bengal produces roughly four times as many as the Arabian Sea. The number varies a lot from year to year.", null, ["nio", "basins", "seasons"]);
E("basins", "What are the cyclone basins of the world?", "basins ocean basins list where do cyclones form regions atlantic pacific indian australian",
  L("Tropical cyclones form in seven main basins:", "• North Atlantic", "• Eastern North Pacific", "• Western North Pacific", "• North Indian Ocean (Bay of Bengal and Arabian Sea)", "• South-West Indian Ocean", "• Australian region", "• South Pacific", "The South Atlantic almost never has them. About 80 to 90 named tropical storms form each year worldwide."), null, ["seasons", "nio"]);
E("seasons", "When is the cyclone season?", "season cyclone season months when peak time of year hurricane season monsoon pre post cyclone season in india months when is the cyclone season when do cyclones occur bay of bengal arabian sea indian season time of year",
  L("The seasons differ by basin:", "• North Atlantic: 1 June to 30 November, peaking in September.", "• Eastern North Pacific: 15 May to 30 November.", "• Western North Pacific: all year, peaking from July to October.", "• North Indian Ocean: two seasons, April to June (pre-monsoon) and October to December (post-monsoon).", "• South-West Indian, Australian and South Pacific: roughly November to April."), null, ["nio", "basins"]);
E("nio", "What are cyclones like in the North Indian Ocean?", "how many cyclones hit india every year how many cyclones per year in india annual average number of cyclones in india each year north indian ocean bay of bengal arabian sea cyclones frequency how many india season facts bimodal",
  "The North Indian Ocean produces only about 5 to 6 percent of the world's tropical cyclones, but they hit densely populated coasts. It has two seasons, April to June (pre-monsoon, peak in May) and October to December (post-monsoon, peak in November). The Bay of Bengal produces roughly four times as many cyclones as the Arabian Sea. Cyclones of the Bay of Bengal usually hit Odisha, Andhra Pradesh, Tamil Nadu, West Bengal, Bangladesh or Myanmar, and those of the Arabian Sea affect Gujarat, Maharashtra, Pakistan, Oman and Yemen.", null, ["whybay", "arabian"]);
E("whybay", "Why does the Bay of Bengal have more cyclones than the Arabian Sea?", "why bay of bengal more cyclones than arabian sea compare difference frequency",
  "The Bay of Bengal is warmer and has a layer of fresh river water that keeps the surface warm. It also gets more disturbances, such as remnants of storms from the western Pacific and the monsoon trough. The Arabian Sea is usually cooler, has stronger wind shear in some seasons, and is more affected by dry air from the north-west.", null, ["nio", "arabian"]);
E("arabian", "Do cyclones hit Mumbai and the west coast of India often?", "can cyclones occur in the arabian sea do cyclones form in arabian sea arabian sea cyclones strongest cyclone in the arabian sea arabian sea cyclone mumbai maharashtra west coast landfall rare konkan gujarat how often",
  "Landfalls on the Maharashtra and Konkan coasts are less common than on India's east coast. Most Arabian Sea cyclones head north-west towards Oman, Yemen or Pakistan, or recurve north-east towards Gujarat. Recent examples that affected the west coast are Nisarga (2020), Tauktae (2021) and Biparjoy (2023). Studies suggest that intense Arabian Sea cyclones have become more frequent in recent decades.", null, ["nisarga", "tauktae", "biparjoy"]);
E("naming", "How are cyclones named?", "naming names how are cyclones named who names list wmo escap panel 13 countries tropical cyclones panel alphabetical",
  "Names are given when a system reaches storm strength (34 kt). In the North Indian Ocean the 13 member countries of the WMO/ESCAP Panel on Tropical Cyclones (Bangladesh, India, Iran, Maldives, Myanmar, Oman, Pakistan, Qatar, Saudi Arabia, Sri Lanka, Thailand, UAE and Yemen) contributed names, and the IMD assigns the next on the list. The practice began in 2004, and a new list of 169 names (13 per country) was adopted in 2020. Names are used because they are easier to remember and avoid confusion when several storms are active.", "Recent names include Biparjoy (Bangladesh), Tej (India), Hamoon (Iran), Midhili (Maldives), Michaung (Myanmar), Remal (Oman), Dana (Qatar) and Fengal (Saudi Arabia).", ["names", "retire"]);
E("retire", "Are cyclone names ever retired?", "retired names retirement deadly cyclone names reuse",
  "Yes. In some basins, such as the Atlantic, the names of especially deadly or costly storms are retired and never used again. The North Indian Ocean list is not reused. Each name is used once.", null, ["naming"]);
E("recentnames", "What are some recent North Indian Ocean cyclone names?", "recent names tej hamoon midhili michaung remal asna dana fengal biparjoy mocha asani names list",
  "Recent North Indian Ocean names include Mocha (Yemen, 2023), Biparjoy (Bangladesh, 2023), Tej (India, 2023), Hamoon (Iran, 2023), Midhili (Maldives, 2023), Michaung (Myanmar, 2023), Remal (Oman, 2024), Dana (Qatar, 2024) and Fengal (Saudi Arabia, 2024).", null, ["naming"]);

/* ---------- history ---------- */
E("records", "What are the cyclone records?", "records strongest deadliest largest longest lowest pressure costliest worst biggest ever recorded most powerful largest biggest in history strongest ever most powerful ever worst ever top cyclone records strongest cyclone ever recorded strongest cyclone in history largest cyclone in history biggest cyclone ever most intense cyclone ever lowest pressure deadliest cyclone in history longest lasting cyclone",
  L("Some well-known records:", "• Deadliest: the 1970 Bhola cyclone, with an estimated 300,000 to 500,000 deaths in Bangladesh.", "• Lowest pressure: Typhoon Tip (1979) at 870 hPa, also the largest, with gale-force winds about 2,200 km across.", "• Strongest winds at landfall: Typhoon Haiyan (2013), about 315 km/h (1-minute average) over the Philippines.", "• Strongest winds worldwide in the Western Hemisphere: Hurricane Patricia (2015), about 345 km/h and 872 hPa.", "• Longest-lived: Hurricane John (1994), 31 days.", "• Among the costliest: Hurricane Katrina (2005)."), null, ["bhola", "haiyan", "katrina"]);
E("bhola", "What was the 1970 Bhola cyclone?", "bhola 1970 cyclone deadliest east pakistan bangladesh deaths deadliest cyclone ever which was the deadliest cyclone in history most deaths worst cyclone ever killed most people deadliest cyclone in history deadliest cyclone ever",
  "The Bhola cyclone struck the Ganges delta in East Pakistan (now Bangladesh) in November 1970. A huge storm surge flooded the low-lying islands, and an estimated 300,000 to 500,000 people died, making it the deadliest tropical cyclone on record.", null, ["records", "bangladesh1991"]);
E("bangladesh1991", "What was the 1991 Bangladesh cyclone?", "1991 bangladesh cyclone chittagong deaths 138000",
  "In April 1991 a severe cyclone with a very high storm surge hit the Chittagong coast of Bangladesh and killed about 138,000 people. It led to a major expansion of cyclone shelters and community warning programmes in Bangladesh.", null, ["bhola"]);
E("odisha1999", "What was the 1999 Odisha super cyclone?", "1999 odisha super cyclone paradip deaths october 1999 orissa",
  "The Odisha super cyclone made landfall near Paradip on 29 October 1999 with winds of about 260 km/h and a surge of several metres. About 10,000 people died. It led to Odisha creating its own state disaster management authority and building many cyclone shelters, which is a main reason for the much lower death tolls in later cyclones such as Phailin and Fani.", null, ["supercyclone", "phailin", "fani"]);
E("nargis", "What was Cyclone Nargis?", "nargis 2008 myanmar irrawaddy delta deaths",
  "Cyclone Nargis struck Myanmar's Irrawaddy delta in May 2008. A surge of several metres flooded the low-lying delta and about 138,000 people died. It is one of the deadliest cyclones on record.", null, ["records"]);
E("haiyan", "What was Typhoon Haiyan?", "haiyan yolanda 2013 philippines typhoon tacloban",
  "Typhoon Haiyan (called Yolanda in the Philippines) hit the central Philippines in November 2013, with winds of about 315 km/h (1-minute average) at landfall, among the strongest ever at landfall. A surge several metres high devastated Tacloban and the storm killed over 6,000 people.", null, ["records"]);
E("phailin", "What was Cyclone Phailin?", "phailin 2013 odisha gopalpur evacuation october 2013",
  "Cyclone Phailin made landfall near Gopalpur, Odisha, on 12 October 2013 as a very severe cyclonic storm. More than a million people were moved to safety before landfall, and deaths were in the tens, compared with around 10,000 in 1999. It is cited as a success of early warning and mass evacuation.", null, ["odisha1999", "hudhud"]);
E("hudhud", "What was Cyclone Hudhud?", "hudhud 2014 visakhapatnam vizag october 2014",
  "Cyclone Hudhud made landfall near Visakhapatnam, Andhra Pradesh, on 12 October 2014 as a very severe cyclonic storm. It damaged the city heavily, especially its trees and power and telecom networks, but the deaths were limited because of evacuations.", null, ["phailin"]);
E("fani", "What was Cyclone Fani?", "fani 2019 puri odisha may 2019 extremely severe",
  "Cyclone Fani made landfall near Puri, Odisha, on 3 May 2019 as an extremely severe cyclonic storm. About 1.2 million people were evacuated in advance, which kept the death toll low despite the strength of the storm.", null, ["odisha1999", "phailin"]);
E("amphan", "What was Cyclone Amphan?", "amphan 2020 west bengal sundarbans kolkata super cyclonic storm bangladesh",
  "Amphan was a super cyclonic storm in the Bay of Bengal in May 2020. It weakened before landfall but was still very severe when it crossed the coast near the Sundarbans in West Bengal on 20 May 2020, causing great damage in Kolkata and southern West Bengal and in Bangladesh.", null, ["supercyclone", "imd"]);
E("nisarga", "What was Cyclone Nisarga?", "nisarga 2020 alibag raigad maharashtra mumbai june 2020",
  "Cyclone Nisarga made landfall near Alibag in Raigad district, Maharashtra, on 3 June 2020 as a severe cyclonic storm. It passed close to Mumbai, and tens of thousands of people were moved out of coastal areas beforehand.", null, ["arabian", "tauktae"]);
E("tauktae", "What was Cyclone Tauktae?", "tauktae 2021 gujarat diu una may 2021 konkan mumbai barge",
  "Cyclone Tauktae formed in the Arabian Sea in May 2021 and became an extremely severe cyclonic storm. It moved up the west coast, passed close to Mumbai (where a barge, P305, sank offshore) and made landfall in Gujarat near Diu and Una on 17 May 2021.", null, ["arabian", "biparjoy"]);
E("biparjoy", "What was Cyclone Biparjoy?", "biparjoy 2023 kutch jakhau gujarat june 2023 longest arabian sea",
  "Cyclone Biparjoy formed in the Arabian Sea in June 2023, was one of the longest-lived cyclones recorded in that sea, and made landfall near Jakhau in Kutch, Gujarat, on 15 June 2023 as a very severe cyclonic storm. Large-scale evacuations kept casualties low.", null, ["arabian", "tauktae"]);
E("vayu", "What was Cyclone Vayu?", "vayu 2019 gujarat skirted veraval june 2019",
  "Cyclone Vayu was a very severe cyclonic storm in the Arabian Sea in June 2019. It skirted the Gujarat coast without making landfall and turned away to the west.", null, ["arabian"]);
E("mocha", "What was Cyclone Mocha?", "mocha 2023 myanmar sittwe bangladesh may 2023",
  "Cyclone Mocha was an extremely severe cyclonic storm that made landfall near Sittwe in Myanmar in May 2023, with a major impact in Rakhine state and in Bangladesh's refugee camps.", null, ["nio"]);
E("michaung", "What was Cyclone Michaung?", "michaung 2023 chennai floods andhra pradesh bapatla december 2023",
  "Cyclone Michaung hit the coast of Andhra Pradesh near Bapatla in December 2023. It brought extreme rain and severe flooding to Chennai and other parts of Tamil Nadu and Andhra Pradesh.", null, ["rain"]);
E("remal", "What was Cyclone Remal?", "remal 2024 west bengal bangladesh may 2024 sagar island",
  "Cyclone Remal, a severe cyclonic storm, made landfall on the coast of Bangladesh and West Bengal in late May 2024, near Sagar Island and Khepupara, bringing strong winds and surge to the Sundarbans region.", null, ["nio"]);
E("dana", "What was Cyclone Dana?", "dana 2024 odisha bhitarkanika dhamra october 2024",
  "Cyclone Dana, a severe cyclonic storm, made landfall near Bhitarkanika and Dhamra in Odisha on 24 to 25 October 2024. Odisha moved large numbers of people to shelters in advance.", null, ["odisha1999"]);
E("fengal", "What was Cyclone Fengal?", "fengal 2024 puducherry tamil nadu december november 2024",
  "Cyclone Fengal made landfall near Puducherry on 30 November 2024 as a cyclonic storm. It stalled over the region and brought very heavy rain and flooding to Tamil Nadu and Puducherry.", null, ["stall"]);
E("katrina", "What was Hurricane Katrina?", "katrina 2005 new orleans louisiana hurricane levee",
  "Hurricane Katrina struck the US Gulf Coast in August 2005. Storm surge broke the levees in New Orleans and flooded most of the city. About 1,800 people died, and damage was around 125 billion US dollars, making it one of the costliest hurricanes ever.", null, ["records", "surge"]);
E("harvey", "What was Hurricane Harvey?", "harvey 2017 houston texas rainfall record flood",
  "Hurricane Harvey made landfall in Texas in August 2017 and then stalled for days. It dropped more than 1,500 mm of rain in some places, causing enormous floods in Houston.", null, ["stall", "rain"]);
E("patricia", "What was Hurricane Patricia?", "patricia 2015 strongest hurricane western hemisphere 872 mexico",
  "Hurricane Patricia in October 2015 reached sustained winds of about 345 km/h and a central pressure of 872 hPa in the eastern Pacific, the strongest hurricane on record in the Western Hemisphere. It weakened rapidly and caused less damage than feared when it hit Mexico.", null, ["records", "rapid"]);
E("tip", "What was Typhoon Tip?", "typhoon tip 1979 largest lowest pressure 870",
  "Typhoon Tip in 1979 had the lowest central pressure ever measured in a tropical cyclone (870 hPa) and was the largest, with gale-force winds across about 2,200 km.", null, ["records", "pressure"]);
E("gonu", "What was Cyclone Gonu?", "gonu 2007 oman arabian sea strongest super cyclonic storm",
  "Cyclone Gonu in June 2007 was one of the strongest cyclones ever recorded in the Arabian Sea. It reached super cyclonic storm strength and hit the coast of Oman.", null, ["arabian"]);

/* ---------- climate ---------- */
E("climate", "How does climate change affect cyclones?", "will there be more cyclones in the future getting worse increasing trend future of cyclones are cyclones getting worse more frequent stronger in future climate change global warming effect cyclones stronger more intense frequency trend sea level rise rainfall does climate change make cyclones stronger more intense global warming effect on cyclones",
  L("Scientific assessments (such as the IPCC) find that a warming climate is likely to:", "• Raise the share of cyclones that reach the most intense categories.", "• Increase rain rates, because warmer air holds more moisture (about 7 percent more per degree of warming).", "• Make rapid intensification and storm surge worse, as sea level rises.", "The total number of cyclones is not expected to increase, and may fall. Studies, including Indian ones, report that intense cyclones in the Arabian Sea have become more frequent in recent decades."), null, ["rapid", "surge"]);
E("enso", "How do El Nino and other climate patterns affect cyclones?", "el nino la nina enso mjo madden julian iod indian ocean dipole climate patterns influence season",
  "In the Pacific and Atlantic, El Niño changes the number and strength of cyclones, for example by suppressing Atlantic hurricanes and shifting typhoon formation eastwards. In the Indian Ocean the Madden-Julian Oscillation (MJO) and the Indian Ocean Dipole influence when and where cyclones form, and storms often form when the MJO is in its active phase over the region.", null, ["seasons"]);
E("monsoon", "How are cyclones related to the monsoon?", "monsoon cyclone relation onset depression low pressure monsoon trough season",
  "A monsoon depression is a different system that forms in the monsoon trough over the Bay of Bengal and moves over India, bringing heavy rain. Cyclones are stronger, warm-core systems that mostly form just before the monsoon (April to June) and just after it (October to December), when winds aloft are light. A cyclone in the Arabian Sea in early June can also pull moisture away and delay the monsoon's progress.", null, ["nio", "lowpressure"]);
E("lowpressure", "What is a low-pressure area or depression?", "low pressure area depression deep depression well marked low what is depression weather system",
  "A low-pressure area is a region where the surface pressure is lower than its surroundings. If it organises, with winds of 17 to 27 kt, the IMD calls it a depression and at 28 to 33 kt a deep depression. At 34 kt it becomes a cyclonic storm and gets a name.", null, ["imd"]);

/* ---------- safety ---------- */
E("before", "What should I do before a cyclone?", "at home how to prepare for a cyclone at home house home safety protect my house before cyclone prepare preparedness what to do before cyclone checklist plan get ready precautions",
  L("Before a cyclone arrives:", "• Follow official bulletins from the IMD and your state authorities.", "• Know your nearest cyclone shelter and evacuation route.", "• Prepare an emergency kit (see the kit entry).", "• Secure or bring in loose objects, and strengthen doors, windows and roofs if you can.", "• Charge phones and power banks, and keep cash.", "• Keep important documents in a waterproof bag.", "• Fishermen should not go to sea and should secure boats."), null, ["kit", "evacuation", "during"]);
E("kit", "What should be in a cyclone emergency kit?", "emergency kit supplies list what to pack go bag food water torch radio first aid medicines documents",
  L("A basic emergency kit has:", "• Drinking water and ready-to-eat dry food for several days.", "• A battery radio, torch and spare batteries.", "• A first-aid kit and any regular medicines.", "• Power bank and a charged phone.", "• Copies of important documents in a waterproof bag.", "• Warm clothing, blankets, hygiene items and some cash."), null, ["before"]);
E("during", "What should I do during a cyclone?", "during cyclone safety stay indoors what to do while cyclone windows shelter advice precautions",
  L("During a cyclone:", "• Stay indoors in a strong building, away from windows and glass.", "• Switch off electricity and gas if instructed or if water is entering.", "• Move to an upper floor if there is flooding, but do not go into an attic with no exit.", "• Listen to the radio for official updates.", "• Do not go outside, even if it suddenly goes calm. It may be the eye."), null, ["eyetrap", "after"]);
E("eyetrap", "Is it safe to go outside when the eye passes?", "eye calm safe go outside lull trap go out outside outdoors safe to go out in the eye calm lull step out",
  "No. The calm in the eye lasts only a short time, and the strongest winds from the other side of the eyewall return suddenly from the opposite direction. Stay inside until officials announce that it is safe.", null, ["eye", "during"]);
E("after", "What should I do after a cyclone?", "after cyclone safety aftermath recovery what to do after flood water wires health",
  L("After a cyclone:", "• Stay in shelter until officials give the all-clear.", "• Stay away from fallen power lines, damaged buildings and flood water.", "• Drink only safe or boiled water and avoid food that has touched flood water.", "• Help neighbours who are elderly or disabled, if it is safe.", "• Report damage and follow official relief instructions."), null, ["during", "health"]);
E("health", "What health risks follow a cyclone?", "health disease cholera water borne diseases injuries mosquitoes after flood",
  "After a cyclone the main risks are injuries from debris and broken glass, drowning in flood water, electrocution from fallen wires, and diseases such as diarrhoea, cholera and leptospirosis from contaminated water. Boil or treat drinking water, wash hands often and get medical help early.", null, ["after"]);
E("evacuation", "When and how should people evacuate?", "evacuation evacuate when to leave shelter move coastal who should evacuate how",
  "Evacuate when the authorities order it, and before the winds reach gale force, because roads become unsafe and shelters hard to reach once the weather turns. People in low-lying coastal areas, near creeks and rivers and in light houses are usually advised to move first, and so are people who need extra time, such as the elderly and the sick. Take the emergency kit, documents and medicines, and move to a cyclone shelter or a sturdy building on higher ground.", null, ["shelters", "kit"]);
E("shelters", "What are cyclone shelters?", "cyclone shelter multipurpose shelter ncrmp what is cyclone shelter safe building",
  "Cyclone shelters are strong buildings, often on raised ground or stilts, designed to resist high winds and flooding and to house people during a cyclone. India has built many multipurpose cyclone shelters, especially in Odisha and Andhra Pradesh, under projects such as the National Cyclone Risk Mitigation Project. In normal times they are often used as schools or community centres.", null, ["evacuation", "agencies"]);
E("fishermen", "What should fishermen do when a cyclone is coming?", "fishermen fishing boats sea trawlers coast guard return harbour safety at sea fisherman fishing community boats trawlers what should fishermen do",
  "Fishermen should not go to sea once a cyclone warning is issued, and boats already out should return to harbour immediately. Boats on shore should be pulled above the high-tide line and secured, and families should move to shelters if told to. The IMD sends warnings to fishermen through the state fisheries departments, the Coast Guard and the Navy.", null, ["before"]);
E("emergency", "Which emergency number can I call in India?", "emergency number india 112 helpline disaster ndma call help",
  "In India the national emergency number is 112. You can also contact your district control room or state disaster management authority helpline, which are announced during a cyclone.", null, ["agencies"]);
E("myths", "What are common cyclone myths?", "myths misconceptions false belief tape windows nuke bomb stop cyclone only coast",
  L("Some common myths:", "• Taping windows prevents them breaking. It does not, and shutters are better.", "• Opening windows equalises pressure. It does not and lets in wind and rain.", "• A cyclone can be stopped or broken up with nuclear bombs. Its energy is far too large.", "• Only people on the coast are at risk. Heavy rain, floods and strong winds can reach far inland.", "• The calm of the eye means it is over. It does not."), null, ["during"]);
E("stop", "Can we stop or control a cyclone?", "stop control weaken cyclone bomb cloud seeding modify nuclear atom bomb blow up destroy break up cloud seeding control the weather",
  "No. A mature cyclone releases enormous amounts of energy, many times more than the world's electricity generation, so ideas such as bombing or cooling the ocean are not practical. What we can do is forecast accurately, warn early, evacuate and build safely.", null, ["myths"]);

/* ---------- more topics ---------- */
E("indiaprone", "Which Indian states are most prone to cyclones?", "which indian state most prone vulnerable cyclone prone states india coastal states east coast west coast odisha andhra pradesh tamil nadu west bengal gujarat exposed",
  "India has a coastline of about 7,500 km, and 13 coastal states and union territories are exposed to cyclones. The east coast (West Bengal, Odisha, Andhra Pradesh, Tamil Nadu and Puducherry) is hit much more often than the west coast, and Odisha and Andhra Pradesh are among the most affected. On the west coast, Gujarat is the most exposed, followed by Maharashtra, with Goa, Karnataka and Kerala less often.", null, ["nio", "arabian"]);
E("inland", "Can a cyclone reach inland cities far from the sea?", "inland far from coast delhi city not near sea can cyclone reach inland effect interior areas cities away from the coast",
  "A cyclone itself weakens quickly after landfall because it loses its supply of warm, moist air, so it does not travel as a cyclone to cities far from the sea. Its remnants can still bring heavy rain, strong winds and floods hundreds of kilometres inland, for a day or more.", null, ["land", "rain"]);
E("effects", "What are the effects of a cyclone?", "effects impact consequences damage caused by cyclone what does a cyclone do destruction loss economic",
  L("A cyclone can cause:", "• Storm surge flooding along the coast.", "• Heavy rain, flash floods and landslides.", "• Destructive winds that damage houses, trees, poles and power lines.", "• Power, water and communication outages, and damaged roads, ports and railways.", "• Loss of crops, livestock and fishing boats, and salt contamination of farmland and drinking water.", "• Injuries, deaths, disease outbreaks and displacement of many people.", "• Large economic loss."), null, ["surge", "rain", "deaths"]);
E("mitigation", "How can the damage from cyclones be reduced?", "reduce damage mitigation prevent protect cyclone proof houses early warning mangroves embankments building codes preparedness measures how to protect from cyclone",
  L("Damage and deaths are reduced by a mix of measures:", "• Accurate forecasts and early warnings that reach everyone.", "• Timely evacuation and strong cyclone shelters.", "• Cyclone-resistant buildings and building codes, and secure power and telecom lines.", "• Protecting mangroves, dunes and coral reefs and building embankments.", "• Land-use and coastal-zone rules that keep new buildings out of the most exposed areas.", "• Community drills and awareness."), "The big drop in deaths in Odisha, from about 10,000 in 1999 to very few in recent cyclones, is credited mostly to early warning, mass evacuation and shelters.", ["shelters", "evacuation", "odisha1999"]);
E("tracking", "Where can I follow real cyclones?", "track real cyclones live where to check cyclone news website app official source current cyclone imd website nhc jtwc windy mausam where can i track cyclones follow cyclones online cyclone tracker track a cyclone live cyclone map",
  "For real cyclones use official sources: the India Meteorological Department (mausam.imd.gov.in and the Mausam app), the US National Hurricane Center (nhc.noaa.gov) for the Atlantic and eastern Pacific, the Joint Typhoon Warning Center, and the national weather services of the country concerned. CycloneX is a prototype with simulated data, so it should not be used for real warnings.", null, ["simulated", "imdwarn"]);
E("tech", "How is CycloneX built?", "technology stack built with react tailwind maplibre recharts fastapi pytorch backend frontend architecture language framework made with how was cyclonex made tech",
  "CycloneX is a web prototype built with React, Tailwind CSS, MapLibre GL for the maps and Recharts for the charts. The data files stand in for the output of a model service (FastAPI with PyTorch models), and the imagery is generated demo imagery that can be swapped for real satellite data.", null, ["aboutcx", "simulated"]);
E("team", "Who built CycloneX?", "who made built created developed developer developers team creators author owner company behind cyclonex",
  "I do not have information about who built CycloneX. What I can tell you is that it is a prototype for disaster management authorities and meteorological departments, built with React, Tailwind CSS and MapLibre GL.", null, ["aboutcx", "tech"]);

/* ---------- glossary ---------- */
E("knot", "What is a knot?", "knot kt knots unit wind speed nautical mile per hour",
  "A knot is one nautical mile per hour. 1 kt is 1.852 km/h or about 1.15 mph. Cyclone wind speeds are given in knots because the unit is standard in meteorology and shipping.", null, ["windconv"]);
E("windconv", "How do I convert between knots, km/h and mph?", "convert conversion knots km/h mph kmph units wind speed conversion formula",
  "Multiply knots by 1.852 to get km/h, and by 1.151 to get mph. Divide km/h by 1.852 to get knots. For example 100 kt is 185 km/h and about 115 mph. You can also ask me directly, for example: convert 90 kt to km/h.", null, ["knot"]);
E("hpa", "What is hPa?", "hpa hectopascal millibar mb unit pressure",
  "The hectopascal (hPa) is the unit of air pressure. One hPa equals one millibar. Normal sea-level pressure is about 1013 hPa.", null, ["pressure"]);
E("convection", "What is convection?", "convection convective thunderstorms rising air meaning",
  "Convection is the rising of warm, moist air to form tall clouds and thunderstorms. Cyclones are powered by convection near their centre.", null, ["energy"]);
E("latent", "What is latent heat?", "latent heat condensation release hidden heat",
  "Latent heat is the energy released when water vapour condenses into liquid droplets. It is the main fuel of a cyclone, because it warms the air in the core and keeps the pressure low.", null, ["energy"]);
E("trough", "What are a trough and a ridge?", "trough ridge pressure pattern subtropical ridge monsoon trough",
  "A trough is an elongated region of low pressure and a ridge is an elongated region of high pressure. Their position decides how cyclones move: a ridge usually steers a storm westwards and a trough can pull it poleward.", null, ["steering"]);

/* ---------- about CycloneX ---------- */
E("simulated", "Is the data in CycloneX real?", "real data simulated demo fake live prototype is this real are the cyclones real actual data synthetic mock",
  "CycloneX is a prototype. As in its documentation, the imagery is generated demo imagery, the verification figures are simulated, and the model outputs (forecasts, alerts and risk data) are simulated stand-ins for the output of a model service. The cyclones shown, including ARB-02, are demonstration scenarios, not real warnings. For real cyclone information always use the India Meteorological Department (IMD) and your state disaster management authority.", null, ["rely", "aboutcx"]);
E("rely", "Can I rely on CycloneX for safety decisions?", "rely trust official safety decision use for real emergency evacuation reliable official warnings",
  "No. CycloneX is a prototype and uses simulated data. For real decisions follow the official warnings of the India Meteorological Department and your state or district disaster management authority.", null, ["simulated", "imdwarn"]);
E("aboutcx", "What is CycloneX?", "cyclonex what is it purpose project prototype who is it for about the website",
  "CycloneX analyses multi-source satellite imagery to identify tropical cyclones, classify their development stage and forecast intensity, track and landfall with a stated confidence. It is a prototype for disaster management authorities and meteorological departments. Its pages show satellite imagery, a prediction view, a global dashboard and an early-warning and decision-support page.", null, ["ai", "simulated"]);
E("who", "Who are you?", "who are you what are you your name are you chatgpt gpt gemini claude llm ai bot human robot assistant introduce yourself are you an ai are you a bot are you a robot are you a human are you real are you chatgpt your name",
  "I am the CycloneX assistant, a built-in program that runs in your browser. I am not ChatGPT or another large language model. I answer from a knowledge base about cyclones and from the live data in CycloneX, so I work offline and never invent figures. If a question is outside my knowledge I will say so.", null, ["aboutcx", "limits"]);
E("limits", "What can't you answer?", "limitations what can you not answer limits weakness cannot do",
  "I can answer questions about cyclone science, scales and names, history, warnings and safety, and everything shown in CycloneX. I cannot give real-time observations or forecasts for real storms, answer questions on unrelated topics, or give medical or legal advice. For real-time storm information use the IMD (mausam.imd.gov.in).", null, ["who", "rely"]);

/* ---------- extra topics added after testing ---------- */
E("quadrant", "Which part of a cyclone is the worst?", "most dangerous part side quadrant right front right of track worst side strongest winds highest surge which side which part dangerous half",
  "In the Northern Hemisphere the right-hand side of the storm, relative to the direction it is moving, is the most dangerous, and the right-front quadrant is the worst. There the storm's own forward speed adds to its rotating winds, and the winds push water onto the coast, so the strongest winds and the highest storm surge occur there. The left side is usually weaker. In the Southern Hemisphere the left side is the dangerous one. The eyewall, the ring of storm clouds around the eye, is the most dangerous part in terms of structure.", "This is why a coastal place just to the right of where the eye crosses the coast often sees the highest surge, while a place on the left may see weaker winds and a surge that is much lower.", ["eyewall", "surge", "structure"]);
E("isro", "What is the role of ISRO in forecasting cyclones?", "isro indian space research organisation insat 3d 3dr 3ds scatsat oceansat mosdac role of isro space agency india satellites navic",
  "ISRO builds and operates the satellites that India's cyclone forecasters depend on. The INSAT-3D, INSAT-3DR and INSAT-3DS meteorological satellites give images of the Indian Ocean every 15 to 30 minutes, and ISRO's SCATSAT-1 and Oceansat-3 carry scatterometers that measure ocean surface winds. The India Meteorological Department (IMD) uses these data for its forecasts and warnings, ISRO's MOSDAC portal distributes them, and NavIC is used to send alerts to fishermen at sea.", null, ["satellites", "scatterometer", "imdwarn"]);
E("aviation", "Do cyclones affect aeroplanes and flights?", "aeroplane airplane aircraft flights flying airport airlines plane aviation flight cancellations turbulence hurricane hunters for aeroplanes",
  "Yes. Aircraft avoid cyclones because of severe turbulence, heavy rain, lightning, icing and sudden wind changes (wind shear) near the storm. Airports in the storm's path usually suspend operations, and flights are cancelled or diverted. Specially equipped research aircraft, often called hurricane hunters, do fly into some storms to measure them, but this is done by trained crews with purpose-built planes.", null, ["effects", "landfall"]);
E("economy", "How do cyclones affect the economy?", "economy economic cost damage money loss losses billion dollars insurance livelihoods agriculture crops fisheries power infrastructure ports how do cyclones affect the economy financial",
  "Cyclones cause economic loss through damaged houses, roads, bridges, power and telecom lines, ports, crops and fishing boats, and through days or weeks of lost business. Poor and coastal communities often lose their livelihoods. Cyclone Amphan (2020) was estimated to have caused over 13 billion US dollars of damage, which makes it among the costliest cyclones in the North Indian Ocean. Early warning and evacuation greatly reduce the loss of life, even when property damage is high.", null, ["effects", "mitigation", "records"]);
E("languages", "What is the word for cyclone in Indian languages?", "hindi name for cyclone word in hindi tamil telugu marathi bengali gujarati odia language translation chakravat toofan puyal tupanu vavazodu batya ghurnijhor chakrivadal how to say cyclone in",
  "Cyclone is chakravat (चक्रवात) in Hindi, and the word toofan or tufan (तूफ़ान) is used in everyday speech for a storm. Other common words: chakrivadal (चक्रीवादळ) in Marathi, ghurnijhor (ঘূর্ণিঝড়) in Bengali, puyal (புயல்) in Tamil, tupanu (తుఫాను) in Telugu, vavazodu (વાવાઝોડું) in Gujarati and batya (ବାତ୍ୟା) in Odia.", null, ["etymology", "naming"]);
E("indialist", "Which cyclones have hit India?", "list of cyclones that hit india notable indian cyclones names famous cyclones in india history list major cyclones indian coast",
  "Notable cyclones that have affected India include the 1977 Andhra Pradesh cyclone, the 1999 Odisha super cyclone, Phailin (2013), Hudhud (2014), Fani (2019), Amphan (2020), Nisarga (2020), Tauktae (2021), Biparjoy (2023), Michaung (2023), Remal (2024), Dana (2024) and Fengal (2024). Most land on the east coast, from Odisha and West Bengal to Andhra Pradesh and Tamil Nadu. On the west coast, Nisarga, Tauktae and Biparjoy are recent examples.", "Ask me about any of them by name, for example Fani, Amphan or Tauktae.", ["odisha1999", "fani", "amphan", "tauktae"]);
E("monsoonvs", "What is the difference between a cyclone and the monsoon?", "difference between cyclone and monsoon monsoon vs cyclone compare same different monsoon winds seasonal rain",
  "They are different things. The monsoon is a seasonal wind pattern that brings widespread rain to India for months, driven by the temperature difference between land and sea. A cyclone is a compact, intense, rotating storm that lasts a few days and has a low-pressure centre and very strong winds. Cyclones usually form in the pre-monsoon (April to June) and post-monsoon (October to December) seasons in the North Indian Ocean, and the monsoon's strong winds and wind shear tend to keep them from forming at its peak.", null, ["monsoon", "nio", "what"]);
E("cxvsimd", "How is CycloneX different from the IMD?", "cyclonex vs imd difference compare official india meteorological department replace unique special different from imd what makes cyclonex unique advantage feature",
  "The IMD is India's official cyclone warning agency, and its bulletins are the ones to follow. CycloneX is a prototype decision-support concept: it combines satellite imagery analysis, a forecast with a stated confidence, risk by district and a suggested timeline of actions in one place. It does not replace the IMD, and its data in this version is simulated.", null, ["rely", "aboutcx", "simulated"]);
E("simple", "Explain a cyclone in simple words", "simple words simply child kid easy explain like i am five eli5 beginner layman basic idea for children what is a cyclone in simple words",
  "A cyclone is a giant spinning storm that forms over warm sea water. The sun warms the sea, water rises as warm moist air, and that air rises and makes clouds. As the air rises, more air rushes in underneath, and because the Earth spins, all of it starts to rotate. The storm keeps growing while it sits over warm water. When it reaches the coast it brings strong winds, heavy rain and a rise in sea level called a storm surge. Once it moves over land it loses its fuel and slowly dies out.", null, ["what", "formation", "before"]);
E("acronyms", "What do the abbreviations IMD, NDMA, NDRF, WMO and RSMC stand for?", "imd stands for ndma ndrf sdrf wmo rsmc incois jtwc nhc sst ace hpa kt insat isro abbreviation acronym full form meaning of abbreviations what does imd stand for what is the full form of what does ndrf stand for",
  "IMD: India Meteorological Department, India's national weather and cyclone warning agency, under the Ministry of Earth Sciences. NDMA: National Disaster Management Authority. NDRF: National Disaster Response Force. SDRF: State Disaster Response Force. INCOIS: Indian National Centre for Ocean Information Services, which gives ocean and storm-surge advisories. WMO: World Meteorological Organization. RSMC: Regional Specialised Meteorological Centre, the agency that issues official cyclone advisories for a region (the IMD in New Delhi for the North Indian Ocean). NHC: US National Hurricane Center. JTWC: US Joint Typhoon Warning Center. SST: sea surface temperature. ACE: accumulated cyclone energy. hPa: hectopascal, the unit of pressure. kt: knot, one nautical mile per hour.", null, ["agencies", "imdwarn", "rsmc"]);